WITH unpacked AS (SELECT id, customer_id, coupon_codes, attributes, TRANSFORM(FILTER(items, li -> li.promo IS NOT NULL), li -> STRUCT(li.product_id AS pid, ROUND(li.price * 0.9, 2) AS discounted_price)) AS promo_lines, TRANSFORM(items, li -> li.product_id) AS product_ids FROM carts) SELECT customer_id, COUNT(DISTINCT customer_id) AS distinct_customer_ids, COUNT(*) AS cnt, COUNT(*) AS event_count FROM unpacked GROUP BY ROLLUP (customer_id) ORDER BY event_count DESC
